-- Jeu de données AfriPay — généré, ne pas éditer à la main.
-- Voir scripts/generate-afripay-seed.ts pour régénérer.


drop table if exists raw_transactions_bronze, fact_transactions, fx_rates, dim_date, dim_merchant, dim_customer, dim_country cascade;

create table dim_country (
  country_code text primary key,
  country_name text not null,
  currency_code text not null,
  region text not null,
  timezone text not null
);

create table dim_customer (
  customer_id serial primary key,
  full_name text not null,
  country_code text references dim_country(country_code),
  signup_date date not null,
  segment text not null check (segment in ('particulier','pme','premium'))
);

create table dim_merchant (
  merchant_id serial primary key,
  merchant_name text not null,
  category text not null,
  country_code text references dim_country(country_code),
  onboarded_date date not null
);

create table dim_date (
  date_key integer primary key,
  date date not null,
  year int not null,
  quarter int not null,
  month int not null,
  week int not null,
  day_of_week int not null,
  is_weekend boolean not null
);

create table fx_rates (
  currency_code text not null,
  rate_date date not null,
  rate_to_usd numeric(14,6) not null,
  primary key (currency_code, rate_date)
);

create table fact_transactions (
  transaction_id serial primary key,
  customer_id int references dim_customer(customer_id),
  merchant_id int references dim_merchant(merchant_id),
  country_code text references dim_country(country_code),
  transaction_at timestamptz not null,
  date_key int references dim_date(date_key),
  amount_local numeric(14,2) not null,
  currency_code text not null,
  channel text not null,
  status text not null check (status in ('completed','failed','pending'))
);

create table raw_transactions_bronze (
  transaction_id text,
  customer_id text,
  merchant_id text,
  country_code text,
  transaction_at_raw text,
  amount_local text,
  currency_code text,
  channel text,
  status text
);

